"use strict";(self.webpackChunktcc_docs=self.webpackChunktcc_docs||[]).push([["3338"],{33639(n,e,r){r.r(e),r.d(e,{metadata:()=>a,default:()=>m,frontMatter:()=>s,contentTitle:()=>t,toc:()=>c,assets:()=>d});var a=JSON.parse('{"id":"Perl/scripts/create_pdf_ata_banca","title":"create_pdf_ata_banca","description":"Apresenta listagem de professores.","source":"@site/docs/Perl/scripts/create_pdf_ata_banca.mdx","sourceDirName":"Perl/scripts","slug":"/Perl/scripts/create_pdf_ata_banca","permalink":"/tcc-docs/docs/Perl/scripts/create_pdf_ata_banca","draft":false,"unlisted":false,"editUrl":"https://github.com/ruseleredu/tcc-docs/edit/main/docs/Perl/scripts/create_pdf_ata_banca.mdx","tags":[],"version":"current","lastUpdatedBy":"Adriano Ruseler","lastUpdatedAt":1789150874000,"sidebarPosition":37,"frontMatter":{"id":"create_pdf_ata_banca","title":"create_pdf_ata_banca","sidebar_position":37,"description":"Apresenta listagem de professores."},"sidebar":"tutorialSidebar","previous":{"title":"close_equipes_orientadores","permalink":"/tcc-docs/docs/Perl/scripts/close_equipes_orientadores"},"next":{"title":"create_pdf_cert_banca","permalink":"/tcc-docs/docs/Perl/scripts/create_pdf_cert_banca"}}'),i=r(74848),o=r(28453);let s={id:"create_pdf_ata_banca",title:"create_pdf_ata_banca",sidebar_position:37,description:"Apresenta listagem de professores."},t="create_pdf_ata_banca.pl",d={},c=[{value:"Overview",id:"overview",level:2},{value:"Perl Modules",id:"perl-modules",level:2},{value:"Database",id:"database",level:2},{value:"Command-Line Options",id:"command-line-options",level:2},{value:"Example",id:"example",level:3},{value:"Source Code",id:"source-code",level:2}];function l(n){let e={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,o.R)(),...n.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(e.header,{children:(0,i.jsx)(e.h1,{id:"create_pdf_ata_bancapl",children:(0,i.jsx)(e.code,{children:"create_pdf_ata_banca.pl"})})}),"\n",(0,i.jsx)(e.p,{children:"Apresenta listagem de professores."}),"\n",(0,i.jsx)(e.h2,{id:"overview",children:"Overview"}),"\n",(0,i.jsx)(e.p,{children:"This page was generated automatically from the Perl source file."}),"\n",(0,i.jsx)(e.h2,{id:"perl-modules",children:"Perl Modules"}),"\n",(0,i.jsx)(e.p,{children:"The script uses the following modules:"}),"\n",(0,i.jsxs)(e.ul,{children:["\n",(0,i.jsx)(e.li,{children:(0,i.jsx)(e.code,{children:"DBI"})}),"\n",(0,i.jsx)(e.li,{children:(0,i.jsx)(e.code,{children:"Getopt::Std"})}),"\n"]}),"\n",(0,i.jsx)(e.h2,{id:"database",children:"Database"}),"\n",(0,i.jsxs)(e.ul,{children:["\n",(0,i.jsxs)(e.li,{children:[(0,i.jsx)(e.strong,{children:"Database interface:"})," MySQL via Perl DBI"]}),"\n"]}),"\n",(0,i.jsx)(e.h2,{id:"command-line-options",children:"Command-Line Options"}),"\n",(0,i.jsxs)(e.table,{children:[(0,i.jsx)(e.thead,{children:(0,i.jsxs)(e.tr,{children:[(0,i.jsx)(e.th,{children:"Option"}),(0,i.jsx)(e.th,{children:"Argument"})]})}),(0,i.jsxs)(e.tbody,{children:[(0,i.jsxs)(e.tr,{children:[(0,i.jsx)(e.td,{children:(0,i.jsx)(e.code,{children:"-w"})}),(0,i.jsx)(e.td,{children:"No"})]}),(0,i.jsxs)(e.tr,{children:[(0,i.jsx)(e.td,{children:(0,i.jsx)(e.code,{children:"-h"})}),(0,i.jsx)(e.td,{children:"No"})]}),(0,i.jsxs)(e.tr,{children:[(0,i.jsx)(e.td,{children:(0,i.jsx)(e.code,{children:"-u"})}),(0,i.jsx)(e.td,{children:"Required"})]}),(0,i.jsxs)(e.tr,{children:[(0,i.jsx)(e.td,{children:(0,i.jsx)(e.code,{children:"-p"})}),(0,i.jsx)(e.td,{children:"Required"})]})]})]}),"\n",(0,i.jsx)(e.h3,{id:"example",children:"Example"}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-bash",children:"perl create_pdf_ata_banca.pl -h\n"})}),"\n",(0,i.jsx)(e.h2,{id:"source-code",children:"Source Code"}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-perl",children:'#!/usr/bin/perl\r\nuse strict;\r\nuse warnings;\r\nuse DBI;\r\nuse Getopt::Std;\r\n\r\n# -----------------------------------------------------------------------------\r\n# Apresenta listagem de professores.\r\n# -----------------------------------------------------------------------------\r\n$|++;\r\nmy $crlf = "\\n";\r\nmy $aplicativo = $0;\r\n\r\n\r\n# defini\xe7\xe3o para acesso do banco (valores default)\r\nmy $host     = "localhost";\r\nmy $database = "DAELT";\r\nmy $usuario  = "";\r\nmy $senha    = "";\r\n\r\n\r\n# Recupera\xe7\xe3o dos par\xe2metros de entrada (via shell)\r\nmy %opcoes=();\r\ngetopts("whu:p:", \\%opcoes);\r\n\r\n$crlf    = "\\r\\n"     if defined $opcoes{w};\r\n$usuario = $opcoes{u} if defined $opcoes{u};\r\n$senha   = $opcoes{p} if defined $opcoes{p};\r\n\r\nif (defined $opcoes{h})\r\n{\r\n	print STDERR "$aplicativo [-w] [-u <usuario>] [-p <senha>]$crlf";\r\n	exit 0;\r\n}\r\n\r\n\r\n# apresenta\xe7\xe3o do programa\r\nprint STDERR "$aplicativo\\::Gera arquivo PDF contendo atas.$crlf";\r\n\r\n\r\n# conex\xe3o com banco de dados\r\nmy ($dbHandle,\r\n    $dbStatement1, $dbStatement2, $dbStatement3);\r\nmy (@dbLinha1, @dbLinha2);\r\n\r\n$dbHandle = DBI->connect("DBI:mysql:database=$database;host=$host",\r\n                         $usuario, $senha,\r\n                         {PrintError => 0, AutoCommit => 0})\r\n	or die "$aplicativo\\::Falha de conex\xe3o ao banco de dados: $DBI::errstr";\r\n\r\n$dbStatement1 = $dbHandle->prepare(\r\n	"SELECT B.ID, B.TITULO, A.DATA_APRESENTACAO " .\r\n	"FROM TCC.BANCAS_EQUIPES A, TCC.EQUIPES B " .\r\n	"WHERE A.ID_EQUIPE = B.ID AND A.ID_TIPO = 4 AND A.DATA_FIM IS NULL AND " .\r\n	      "B.DATA_FIM IS NULL " .\r\n	"ORDER BY A.DATA_APRESENTACAO, HORA_APRESENTACAO;");\r\n$dbStatement2 = $dbHandle->prepare(\r\n	"SELECT B.NOME " .\r\n	"FROM TCC.EQUIPES_ALUNOS A, DAELT.ALUNOS B " .\r\n	"WHERE A.ID_EQUIPE = ? AND A.ID_ALUNO = B.ID AND A.DATA_FIM IS NULL " .\r\n	"ORDER BY B.NOME;");\r\n$dbStatement3 = $dbHandle->prepare(\r\n	"SELECT B.CURSO " .\r\n	"FROM TCC.EQUIPES_DISCIPLINAS A, DAELT.DOMINIO_DISCIPLINAS B " .\r\n	"WHERE A.ID_EQUIPE = ? AND A.ID_DISCIPLINA = B.ID AND " .\r\n	      "A.DATA_FIM IS NULL;");\r\n\r\n\r\n# declaracao de algumas funcoes\r\nsub get_data_extenso;\r\nsub get_data_superextenso;\r\n\r\n\r\n# impress\xe3o do pre\xe2mbulo (conforme p\xe1gina)\r\nprint <<PREAMBULO_DOCUMENTO;\r\n\\\\documentclass[11pt,a4paper,notitlepage]{article}\r\n\r\n\\\\usepackage[brazil]{babel}          % pacote de hifena\xe7\xe3o para Brasil\r\n\\\\usepackage[latin1,utf8]{inputenc}  % tipo de caracter (acentua\xe7\xe3o)\r\n\\\\usepackage[T1]{fontenc}            % codifica\xe7\xe3o de fontes\r\n\r\n\\\\usepackage{fullpage}\r\n\\\\usepackage{amsmath}\r\n\\\\usepackage{amsfonts}\r\n\\\\usepackage{amssymb}\r\n\\\\usepackage{graphicx}\r\n\\\\usepackage{icomma}\r\n\\\\usepackage{float}    % permite [H] de figure funcionar como deve!\r\n\\\\usepackage[top=15mm, bottom=20mm, left=30mm, right=15mm]{geometry}\r\n\\\\usepackage{setspace}\r\n\r\n\\\\pagestyle{empty}\r\n\r\n\\\\begin{document}\r\n\r\nPREAMBULO_DOCUMENTO\r\n\r\n# imprime 1 p\xe1gina por orientador/co-orientador\r\n$dbStatement1->execute();\r\n\r\nmy $checa_existencia = 0;\r\nwhile ( @dbLinha1 = $dbStatement1->fetchrow_array )\r\n{\r\n	print "$crlf\\\\newpage$crlf$crlf" if $checa_existencia == 1;\r\n	$checa_existencia = 1;\r\n\r\n	my $equipe_id = $dbLinha1[0];\r\n	$equipe_id =~ s/_/\\\\_/g;\r\n\r\n	# ajuste de datas\r\n	my $data = $dbLinha1[2];\r\n\r\n	my $data_extenso      = get_data_extenso($data);\r\n	my $data_superextenso = get_data_superextenso($data);\r\n\r\n	$dbStatement3->bind_param(1, $dbLinha1[0]);\r\n	$dbStatement3->execute();\r\n\r\n	@dbLinha2 = $dbStatement3->fetchrow_array;\r\n	while ( $dbStatement3->fetchrow_array )\r\n	{\r\n	}\r\n\r\nprint <<PREAMBULO_PAGINA;\r\n% ------------------------------- nova se\xe7\xe3o\r\n\r\n\\\\noindent Universidade Tecnol\xf3gica Federal do Paran\xe1\\\\\\\\\r\nDepartamento Acad\xeamico de Eletrot\xe9cnica\\\\\\\\\r\nCurso de $dbLinha2[0]\r\n\r\n\\\\begin{doublespacing}\r\n\r\n\\\\begin{center}\r\n\\\\bfseries\r\n\\\\Large\r\nAta de Avalia\xe7\xe3o de Trabalho de Conclus\xe3o de Curso\r\n\\\\end{center}\r\n\r\n$data_superextenso, no \\\\textit{Campus} de Curitiba da Universidade Tecnol\xf3gica Federal do Paran\xe1, reuniu-se a banca de avalia\xe7\xe3o de Trabalho de Conclus\xe3o de Curso composta pelos examinadores:\r\n\r\n\\\\begin{spacing}{2}\r\n\\\\begin{center}\r\n1) \\\\rule{9cm}{0.5pt}\\\\\\\\\r\n2) \\\\rule{9cm}{0.5pt}\\\\\\\\\r\n3) \\\\rule{9cm}{0.5pt}\\\\\\\\\r\n4) \\\\rule{9cm}{0.5pt}\r\n\\\\end{center}\r\n\\\\end{spacing}\r\n\r\n\\\\noindent para deliberar o trabalho intitulado\r\n\r\n\\\\begin{singlespacing}\r\n\\\\begin{center}\r\n$equipe_id | $dbLinha1[1]\r\n\\\\end{center}\r\n\\\\end{singlespacing}\r\n\r\nPREAMBULO_PAGINA\r\n\r\n	print "\\\\noindent realizado ";\r\n\r\n	$dbStatement2->bind_param(1, $dbLinha1[0]);\r\n	$dbStatement2->execute();\r\n\r\n	my @lista_alunos;\r\n	while ( @dbLinha2 = $dbStatement2->fetchrow_array )\r\n	{\r\n		push @lista_alunos, $dbLinha2[0];\r\n	}\r\n\r\n	my $lista_alunosSize = scalar(@lista_alunos);\r\n	if ($lista_alunosSize==1 )\r\n	{\r\n		print "pelo aluno:$crlf" .\r\n		      "\\\\begin{singlespacing}$crlf" .\r\n		      "\\\\begin{center}$crlf" .\r\n		      "$lista_alunos[0]$crlf" .\r\n		      "\\\\end{center}$crlf" .\r\n		      "\\\\end{singlespacing}$crlf";\r\n	}\r\n	else\r\n	{\r\n		print "pelos alunos:$crlf" .\r\n		      "\\\\begin{singlespacing}$crlf" .\r\n		      "\\\\begin{center}$crlf";\r\n		for (my $i=0; $i<$lista_alunosSize-1; $i++)\r\n		{\r\n			print "$lista_alunos[$i]\\\\\\\\$crlf";\r\n		}\r\n		print "$lista_alunos[$lista_alunosSize-1]$crlf";\r\n		print "\\\\end{center}$crlf" .\r\n		      "\\\\end{singlespacing}$crlf";\r\n	}\r\n\r\nprint <<PERORACAO_PAGINA;\r\n\r\nComo resultado da avalia\xe7\xe3o, o trabalho foi considerado \\\\rule{6cm}{0.5pt} com nota \\\\rule{6cm}{0.5pt}, lavrando-se ent\xe3o a presenta ata que, ap\xf3s ser lida e aprovada por todos os examinadores, foi por eles assinada.\r\n\r\n\\\\begin{flushright}\r\nCuritiba, $data_extenso.\r\n\\\\end{flushright}\r\n\r\n\\\\begin{spacing}{2}\r\n\\\\begin{center}\r\n1) \\\\rule{9cm}{0.5pt}\\\\\\\\\r\n2) \\\\rule{9cm}{0.5pt}\\\\\\\\\r\n3) \\\\rule{9cm}{0.5pt}\\\\\\\\\r\n4) \\\\rule{9cm}{0.5pt}\r\n\\\\end{center}\r\n\\\\end{spacing}\r\n\r\n\\\\end{doublespacing}\r\nPERORACAO_PAGINA\r\n}\r\n\r\n\r\n# impress\xe3o da peroracao (conforme p\xe1gina)\r\nprint <<PERORACAO_DOCUMENTO;\r\n\r\n\\\\end{document}\r\nPERORACAO_DOCUMENTO\r\n\r\n# desconex\xe3o com banco de dados\r\n$dbHandle->disconnect();\r\nexit 0;\r\n\r\n\r\n# -----------------------------------------------------------------------------\r\n# fun\xe7\xf5es de manipula\xe7\xe3o de data\r\n# -----------------------------------------------------------------------------\r\nsub get_data_extenso()\r\n{\r\n	my $data = $_[0];\r\n	my @informacao = split(\'-\', $data);\r\n	my $mes;\r\n\r\n	$mes = "janeiro"   if $informacao[1] == 1;\r\n	$mes = "fevereiro" if $informacao[1] == 2;\r\n	$mes = "mar\xe7o"     if $informacao[1] == 3;\r\n	$mes = "abril"     if $informacao[1] == 4;\r\n	$mes = "maio"      if $informacao[1] == 5;\r\n	$mes = "junho"     if $informacao[1] == 6;\r\n	$mes = "julho"     if $informacao[1] == 7;\r\n	$mes = "agosto"    if $informacao[1] == 8;\r\n	$mes = "setembro"  if $informacao[1] == 9;\r\n	$mes = "outubro"   if $informacao[1] == 10;\r\n	$mes = "novembro"  if $informacao[1] == 11;\r\n	$mes = "dezembro"  if $informacao[1] == 12;\r\n\r\n	return "$informacao[2] de $mes de $informacao[0]";\r\n}\r\n\r\n\r\nsub get_data_superextenso()\r\n{\r\n	my $data = $_[0];\r\n	my @informacao = split(\'-\', $data);\r\n	my ($dia, $mes, $ano, $ano_numerico);\r\n\r\n	$dia = "Ao primeiro dia"         if $informacao[2] == 1;\r\n	$dia = "Aos dois dias"           if $informacao[2] == 2;\r\n	$dia = "Aos tr\xeas dias"           if $informacao[2] == 3;\r\n	$dia = "Aos quatro dias"         if $informacao[2] == 4;\r\n	$dia = "Aos cinco dias"          if $informacao[2] == 5;\r\n	$dia = "Aos seis dias"           if $informacao[2] == 6;\r\n	$dia = "Aos sete dias"           if $informacao[2] == 7;\r\n	$dia = "Aos oito dias"           if $informacao[2] == 8;\r\n	$dia = "Aos nove dias"           if $informacao[2] == 9;\r\n\r\n	$dia = "Aos dez dias"            if $informacao[2] == 10;\r\n	$dia = "Aos onze dias"           if $informacao[2] == 11;\r\n	$dia = "Aos doze dias"           if $informacao[2] == 12;\r\n	$dia = "Aos treze dias"          if $informacao[2] == 13;\r\n	$dia = "Aos quatorze dias"       if $informacao[2] == 14;\r\n	$dia = "Aos quinze dias"         if $informacao[2] == 15;\r\n	$dia = "Aos dezesseis dias"      if $informacao[2] == 16;\r\n	$dia = "Aos dezessete dias"      if $informacao[2] == 17;\r\n	$dia = "Aos dezoito dias"        if $informacao[2] == 18;\r\n	$dia = "Aos dezenove dias"       if $informacao[2] == 19;\r\n\r\n	$dia = "Aos vinte dias"          if $informacao[2] == 20;\r\n	$dia = "Aos vinte e um dias"     if $informacao[2] == 21;\r\n	$dia = "Aos vinte e dois dias"   if $informacao[2] == 22;\r\n	$dia = "Aos vinte e tr\xeas dias"   if $informacao[2] == 23;\r\n	$dia = "Aos vinte e quatro dias" if $informacao[2] == 24;\r\n	$dia = "Aos vinte e cinco dias"  if $informacao[2] == 25;\r\n	$dia = "Aos vinte e seis dias"   if $informacao[2] == 26;\r\n	$dia = "Aos vinte e sete dias"   if $informacao[2] == 27;\r\n	$dia = "Aos vinte e oito dias"   if $informacao[2] == 28;\r\n	$dia = "Aos vinte e nove dias"   if $informacao[2] == 29;\r\n\r\n	$dia = "Aos trinta dias"         if $informacao[2] == 30;\r\n	$dia = "Aos trinta e um dias"    if $informacao[2] == 31;\r\n	$dia = "Aos trinta e dois dias"  if $informacao[2] == 32;\r\n\r\n	$mes = "janeiro"   if $informacao[1] == 1;\r\n	$mes = "fevereiro" if $informacao[1] == 2;\r\n	$mes = "mar\xe7o"     if $informacao[1] == 3;\r\n	$mes = "abril"     if $informacao[1] == 4;\r\n	$mes = "maio"      if $informacao[1] == 5;\r\n	$mes = "junho"     if $informacao[1] == 6;\r\n	$mes = "julho"     if $informacao[1] == 7;\r\n	$mes = "agosto"    if $informacao[1] == 8;\r\n	$mes = "setembro"  if $informacao[1] == 9;\r\n	$mes = "outubro"   if $informacao[1] == 10;\r\n	$mes = "novembro"  if $informacao[1] == 11;\r\n	$mes = "dezembro"  if $informacao[1] == 12;\r\n\r\n	$ano_numerico = $informacao[0] - 2000;\r\n\r\n	$ano = "dez"        if $ano_numerico == 10;\r\n	$ano = "onze"       if $ano_numerico == 11;\r\n	$ano = "doze"       if $ano_numerico == 12;\r\n	$ano = "treze"      if $ano_numerico == 13;\r\n	$ano = "quatorze"   if $ano_numerico == 14;\r\n	$ano = "quinze"     if $ano_numerico == 15;\r\n	$ano = "dezesseis"  if $ano_numerico == 16;\r\n	$ano = "dezessete"  if $ano_numerico == 17;\r\n	$ano = "dezoito"    if $ano_numerico == 18;\r\n	$ano = "dezenove"   if $ano_numerico == 19;\r\n	$ano = "vinte"      if $ano_numerico == 20;\r\n\r\n	return "$dia do m\xeas de $mes de dois mil e $ano";\r\n}\n'})})]})}function m(n={}){let{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,i.jsx)(e,{...n,children:(0,i.jsx)(l,{...n})}):l(n)}},28453(n,e,r){r.d(e,{R:()=>s,x:()=>t});var a=r(96540);let i={},o=a.createContext(i);function s(n){let e=a.useContext(o);return a.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function t(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(i):n.components||i:s(n.components),a.createElement(o.Provider,{value:e},n.children)}}}]);